strengths = list(map(int, input().split()))
t = int(input())
queries = [tuple(map(int, input().split())) for _ in range(t)]

for l, r in queries:
    segment = strengths[l-1:r]
    unique_strengths = set(segment)
    count = 0
    for s in unique_strengths:
        # Check if s divides all other strengths in the segment
        is_divisor = True
        for other in segment:
            if other % s != 0:
                is_divisor = False
                break
        if is_divisor:
            count += 1
    print((r - l + 1) - count)
"}

