def solve():
    n, h, l, r = map(int, input().split())
    a = list(map(int, input().split()))

    # dp[i][t] = maximum good sleeps after i sleeps with current time t
    dp = [[-1 for _ in range(h)] for _ in range(n + 1)]
    dp[0][0] = 0  # start at time 0 with 0 good sleeps

    for i in range(n):
        for t in range(h):
            if dp[i][t] == -1:
                continue

            # Sleep after a[i] hours
            new_time = (t + a[i]) % h
            if dp[i+1][new_time] < dp[i][t] + (1 if l <= new_time <= r else 0):
                dp[i+1][new_time] = dp[i][t] + (1 if l <= new_time <= r else 0)

            # Sleep after a[i] - 1 hours
            new_time = (t + a[i] - 1) % h
            if dp[i+1][new_time] < dp[i][t] + (1 if l <= new_time <= r else 0):
                dp[i+1][new_time] = dp[i][t] + (1 if l <= new_time <= r else 0)

    print(max(dp[n][t] for t in range(h)))

solve()

