def longest_chain_length(strings):
    # Build graph
    graph = {}
    for a, b in strings:
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

    # Find longest path using DFS with memoization
    max_length = 0

    def dfs(node, path):
        nonlocal max_length

        # Check if we've visited this node before
        if node in path:
            return

        path.append(node)

        # Update max length
        max_length = max(max_length, len(path))

        # Recursively visit neighbors
        for neighbor in graph.get(node, []):
            dfs(neighbor, path)

        path.pop()

    # Start from each node
    for node in graph:
        dfs(node, [])

    return max_length

# Read input
import sys

for line in sys.stdin:
    n = int(line.strip())

    if n == 0:
        break

    strings = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().strip().split())
        strings.append((a, b))

    result = longest_chain_length(strings)
    print(result)
"}

