def next_permutation(digits):
    """Generate the next lexicographical permutation of the digits."""
    # Find the largest index i such that digits[i] < digits[i+1]
    i = len(digits) - 2
    while i >= 0 and digits[i] >= digits[i+1]:
        i -= 1

    if i < 0:
        return None  # No more permutations

    # Find the largest index j > i such that digits[j] > digits[i]
    j = len(digits) - 1
    while digits[j] <= digits[i]:
        j -= 1

    # Swap digits[i] and digits[j]
    digits[i], digits[j] = digits[j], digits[i]

    # Reverse the suffix starting at i+1
    digits[i+1:] = digits[i+1:][::-1]

    return digits

def find_kth_number(digits, k, ascending=True):
    """Find the k-th smallest or largest number that can be formed."""
    if ascending:
        # Start with the smallest number (sorted ascending)
        current = sorted(digits)
    else:
        # Start with the largest number (sorted descending)
        current = sorted(digits, reverse=True)

    for _ in range(k - 1):
        current = next_permutation(current)
        if current is None:
            return None

    return int(''.join(map(str, current)))

