    mocha_id = [get_component_id(n, mocha_components, i) for i in range(n + 1)]
    diana_id = [get_component_id(n, diana_components, i) for i in range(n + 1)]

    # Try to add edges
    added_edges = []
    visited = [False] * (n + 1)

    for node in range(1, n + 1):
        if not visited[node]:
            # Find all nodes in the same component in both forests
