import sys

def mst(points):
    """Compute MST for a list of points on a number line"""
    if len(points) <= 1:
        return 0

    # Sort by position
    points.sort()

    # MST: connect consecutive points
    total = 0
    for i in range(1, len(points)):
        total += points[i] - points[i-1]

    return total

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    green = []
    red = []
    blue = []

    idx = 1
    for _ in range(n):
        pos = int(data[idx])
        color = data[idx + 1]
        idx += 2

        if color == 'G':
            green.append(pos)
        elif color == 'R':
            red.append(pos)
        elif color == 'B':
            blue.append(pos)

    # Compute MST for each color
    mst_green = mst(green)
    mst_red = mst(red)
    mst_blue = mst(blue)

    # Find minimum distance between green and red
    min_green_red = float('inf')
    if green and red:
        for g in green:
            for r in red:
                min_green_red = min(min_green_red, abs(g - r))

    # Find minimum distance between green and blue
    min_green_blue = float('inf')
    if green and blue:
        for g in green:
            for b in blue:
                min_green_blue = min(min_green_blue, abs(g - b))

    total = mst_green + mst_red + mst_blue + min_green_red + min_green_blue

    print(total)

if __name__ == "__main__":
    solve()
