from collections import deque

def solve():
    # Read input
    data = []
    while True:
        try:
            line = input().strip()
            if line:
                data.append(line)
        except EOFError:
            break

    if not data:
        return

    # Parse input
    first_line = data[0].split()
    V = int(first_line[0])
    E = int(first_line[1])
    K = int(first_line[2])

    # Build adjacency list
    adj = [[] for _ in range(V)]
    for i in range(1, len(data)):
        parts = data[i].split()
        v1 = int(parts[0])
        v2 = int(parts[1])
        c = int(parts[2])
        adj[v1].append((v2, c))

    # BFS by number of arrows
    # Track visited states: (current_cone, number_of_arrows) -> max_score
    visited = {}

    # Queue: (number_of_arrows, total_score, current_cone, path)
    queue = deque()

    # Initialize with all cones
    for v in range(V):
        queue.append((0, 0, v, [v]))

    best = None

    while queue:
        arrows, score, v, path = queue.popleft()

        # Check if we've reached the goal
        if score >= K:
            if best is None or arrows < best[0] or (arrows == best[0] and score > best[1]):
                best = (arrows, score, path)
            continue

        # Skip if we've already found a better path to this state
        state_key = (v, arrows)
        if state_key in visited:
            if visited[state_key] >= score:
                continue

        visited[state_key] = score

        # Explore all outgoing arrows
        for next_v, cost in adj[v]:
            new_arrows = arrows + 1
            new_score = score + cost
            new_path = path + [next_v]

            # Check if we've reached the goal
            if new_score >= K:
                if best is None or new_arrows < best[0] or (new_arrows == best[0] and new_score > best[1]):
                    best = (new_arrows, new_score, new_path)

            # Add to queue
            queue.append((new_arrows, new_score, next_v, new_path))

    if best is None:
        print(-1)
    else:
        arrows, score, path = best
        print(arrows)
        if arrows <= 100:
            print(' '.join(map(str, path)))

solve()
