for _ in range(t):
    n, k = map(int, input().split())

    # Calculate where A wants to be at hour k
    if k % n == 0:
        a_desired = 1
    else:
        a_desired = n - (k % n) + 1

    # Calculate where B would be at hour k without any collisions
    if k % n == 0:
        b_base = n
    else:
        b_base = k % n

    # Count how many collisions B has experienced up to hour k-1
    collisions = 0
    for hour in range(1, k):
        # Calculate where A wants to be at this hour
        if hour % n == 0:
            a_hour = 1
        else:
            a_hour = n - (hour % n) + 1

        # Calculate where B would be at this hour without collisions
        if hour % n == 0:
            b_hour = n
        else:
            b_hour = hour % n

        # Check for collision
        if a_hour == b_hour:
            collisions += 1

    # Calculate B's final position
    if a_desired == b_base:
        # Collision at hour k
        if b_base == n:
            b_final = 1
        else:
            b_final = b_base + 1
    else:
        # No collision at hour k, but account for previous collisions
        b_final = b_base + collisions

        # Wrap around if needed
        if b_final > n:
            b_final = b_final % n
            if b_final == 0:
                b_final = n

    print(b_final)
