def count_valid_sequences(n, k):
    """Count the number of valid answer sequences where exactly k people apparently lie."""

    # Try all possible answer sequences
    count = 0
    for answers in range(1, n + 1):
        # Try all possible assignments of who is honest/liar
        for honest_mask in range(1 << n):
            # Count how many people apparently lie
            lies = 0
            for i in range(n):
                if honest_mask & (1 << i):
                    # Honest person says the correct answer
                    correct_answer = bin(honest_mask).count('1')
                    if answers != correct_answer:
                        lies += 1
                else:
                    # Liar says something other than the correct answer
                    correct_answer = bin(honest_mask).count('1')
                    if answers == correct_answer:
                        lies += 1

            if lies == k:
                count += 1

    return count

