def shortest_common_supersequence_length(s1, s2):
    """Compute the length of the shortest common supersequence of s1 and s2."""
    m, n = len(s1), len(s2)
    # dp[i][j] = length of SCS for s1[:i] and s2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1])

    return dp[m][n]

def solve():
    import sys
    input = sys.stdin.read().split()
    idx = 0

    while True:
        n = int(input[idx])
        idx += 1
        if n == 0:
            break

        names = []
        for _ in range(n):
            names.append(input[idx])
            idx += 1

        # Precompute SCS lengths for all pairs
        scs = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                scs[i][j] = shortest_common_supersequence_length(names[i], names[j])

        # DP with bitmask
        dp = [float('inf')] * (1 << n)
        dp[0] = 0

        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    # Try adding string i to the set represented by mask
                    new_mask = mask | (1 << i)
                    dp[new_mask] = min(dp[new_mask], dp[mask] + scs[i][mask.bit_count()])

        print(dp[(1 << n) - 1])

solve()
