MOD = 10**9 + 7

# Precompute factorials and inverse factorials up to 10^5
max_n = 10**5 + 10
fact = [1] * max_n
inv_fact = [1] * max_n

for i in range(1, max_n):
    fact[i] = fact[i-1] * i % MOD

inv_fact[max_n - 1] = pow(fact[max_n - 1], MOD - 2, MOD)
for i in range(max_n - 2, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def comb(n, k):
    """n choose k"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

# Precompute Möbius function for numbers up to 10^5
mu = [1] * (max_n + 1)
min_prime = [0] * (max_n + 1)

for i in range(2, max_n + 1):
    if min_prime[i] == 0:
        min_prime[i] = i
        for j in range(i * i, max_n + 1, i):
            if min_prime[j] == 0:
                min_prime[j] = i

for i in range(2, max_n + 1):
    if min_prime[i] == i:
        # i is prime
        mu[i] = -1
    else:
        # i has a prime factor
        p = min_prime[i]
        if i // p % p == 0:
            # i has at least two factors of p
            mu[i] = 0
        else:
            # i has exactly one factor of p
            mu[i] = mu[i // p]

q = int(input())
for _ in range(q):
    n, f = map(int, input().split())

    if f > n or f < 1:
        print(0)
        continue

    ans = 0
    for d in range(1, n + 1):
        if n % d == 0:
            ans = (ans + mu[d] * comb((n // d) - 1, f - 1)) % MOD

    print(ans)
"}

